 "content": "def transform(grid):
    out = [row[:] for row in grid]
    # The lower two-row motif continues the alternating 8/3 pattern visible
    # in its preceding cells; 3s occupying the expected 8 slots are marked 1.
    if len(grid) >= 2:
        for r in (len(grid)-5, len(grid)-4):
            row = grid[r]
            # Find the final alternating 3/8 sequence and continue its phase.
            seq = [(c, row[c]) for c in range(len(row)) if row[c] in (3, 8)]
            run = []
            for c, v in seq:
                if run and (c != run[-1][0]+1 or v == run[-1][1]):
                    run = []
                run.append((c, v))
            if len(run) >= 3:
                start = run[-1][0] + 1
                expected = 3 if run[-1][1] == 8 else 8
                for c in range(start, len(row)):
                    if row[c] == 3 and expected == 8:
                        out[r][c] = 1
                    expected = 3 if expected == 8 else 8
    return out

